// DEMO DATA ONLY, generated from the printed menu of Steinofen Pizzeria Niki (Wesel). Used when BuildConfig.USE_MOCK_DATA is true.
// Allergen footnotes are left out. Items 91 to 94 and 120 to 124 do not exist on the printed menu.
// Read with doubt (creases or glare on the photo), please check against the printed menu: 14 Hawaii and 15 Mediterrane (larger sizes),
// 107 Insalata Pollo (description cut off), 140 Napoli (number hidden), 151 Quattro Formaggi (price hidden, read as 8,50).
// "Popular" (bestseller) flags on six classic pizzas are an invention for the demo. "Pizza Niki" is marked non-vegetarian because it is a surprise.
// Not modelled: "Jede weitere Zutat" (0,50 / 1,00 / 2,50 by pizza size), because an option's price can't depend on the size.

internal fun euros(cents: Long) = Money(cents)

private fun group(id: String, name: String, required: Boolean, min: Int, max: Int, vararg options: Pair<String, Long>) = CustomizationGroup(
    id = id, name = name, isRequired = required, minSelections = min, maxSelections = max,
    options = options.mapIndexed { i, (label, price) -> CustomizationOption("$id-$i", label, euros(price)) },
)

private val pastaNames = listOf("Spaghetti", "Rigatoni", "Tortellini", "Tagliatelle")

/** The customer picks the pasta; each dish lists its own default first, so it is the preselected one. */
private fun pasta(default: String) = group(
    "g-pasta-$default".lowercase(), "Nudelsorte", true, 1, 1,
    *(listOf(default) + pastaNames.filter { it != default }).map { it to 0L }.toTypedArray(),
)

private val pastaSpaghetti = pasta("Spaghetti")
private val pastaRigatoni = pasta("Rigatoni")
private val pastaTortellini = pasta("Tortellini")
private val pastaTagliatelle = pasta("Tagliatelle")
